/* Review-only in-memory interactions; no backend requests. */
const IntegrationLab={template:`<section class="card body" style="margin-bottom:16px"><div class="tools"><strong>新增交互预演</strong><span class="count">内存示例 · 不提交平台数据</span></div><a-tabs v-model:active-key="tab"><a-tab-pane key="import" title="导入 → 计划与评审"><div class="row"><a-button type="primary" @click="begin">模拟导入2条用例</a-button><span class="count">首次自动创建；再次导入按选择更新、新建或仅导入</span></div><a-alert v-if="message" style="margin-top:12px">{{message}}</a-alert><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px"><div><h4>计划</h4><div v-for="g in groups" :key="g.id" class="row" style="margin:8px 0"><a-button type="text" @click="open(g,'plan')">{{g.plan}}</a-button><span class="count">{{g.ids.length}} 条用例</span></div></div><div><h4>评审</h4><div v-for="g in groups" :key="g.id" class="row" style="margin:8px 0"><a-button type="text" @click="open(g,'review')">{{g.review}}</a-button><span class="count">{{g.ids.length}} 条用例</span></div></div></div><div class="row" style="margin-top:12px"><span>源用例：</span><a-tag v-for="c in cases" :key="c" closable @close="remove(c)">{{c}}</a-tag><span class="count">点 × 模拟删除，计划/评审数量同步减少</span></div></a-tab-pane><a-tab-pane key="assets" title="资产目录与置顶"><div class="row"><a-input v-model="projectName" style="width:220px" placeholder="新增项目名称"/><a-button type="primary" @click="addProject">模拟新建项目</a-button><a-button @click="sync">模拟源用例更新</a-button></div><div v-for="a in ordered" :key="a.id" class="folder row" style="justify-content:space-between;border-bottom:1px solid #eee;padding:10px"><span>{{a.pinned?'📌 ':''}}▱ {{a.name}}　<span class="count">源项目绑定 · {{a.count}} 条用例 · v{{a.version}}</span></span><a-button type="text" @click="a.pinned=!a.pinned">{{a.pinned?'取消置顶':'置顶'}}</a-button></div><p class="count">演示个人置顶和来源更新；真实事件、持久化及权限按整合方案实施。</p></a-tab-pane></a-tabs><a-modal v-model:visible="ask" title="检测到再次导入测试用例" :footer="false" :mask-closable="false"><template v-if="step===1"><p>是否更新已有测试计划和评审计划？将增量关联本次导入的2条用例。</p><a-select v-model="target" style="width:100%"><a-option v-for="g in groups" :key="g.id" :value="g.id">{{g.plan}} / {{g.review}}</a-option></a-select><div class="row" style="margin-top:16px"><a-button type="primary" @click="commit('append')">是，更新已有</a-button><a-button @click="step=2">否</a-button><a-button @click="ask=false">取消导入</a-button></div></template><template v-else><p>是否新建测试计划和评审计划，并关联本次导入用例？</p><div class="row"><a-button type="primary" @click="commit('new')">是，新建并关联</a-button><a-button @click="commit('only')">否，仅导入</a-button><a-button @click="ask=false">取消导入</a-button></div></template></a-modal><a-modal v-model:visible="detail" :title="detailTitle" @ok="detail=false"><p>当前关联 {{detailIds.length}} 条用例：{{detailIds.join('、')||'暂无'}}</p><p class="count">名称链接与详情入口一致；这里只展示内存中的关联结果。</p></a-modal></section>`,setup(){const{ref,computed}=Vue;const tab=ref('import'),groups=ref([]),cases=ref([]),ask=ref(false),step=ref(1),target=ref(''),message=ref(''),detail=ref(false),detailTitle=ref(''),detailIds=ref([]),projectName=ref(''),assets=ref([{id:1,name:'MSP需求验收项目',count:6,version:1,pinned:false},{id:2,name:'订单质量回归',count:4,version:1,pinned:false}]);let seq=0;function begin(){if(!groups.value.length)commit('new');else{step.value=1;target.value=groups.value.at(-1).id;ask.value=true}}function commit(policy){let ids=['导入用例-'+(++seq),'导入用例-'+(++seq)];cases.value.push(...ids);if(policy==='new'){let id=String(groups.value.length+1);groups.value.push({id,plan:'导入测试计划-'+id,review:'导入评审计划-'+id,ids:[...ids]})}else if(policy==='append'){let g=groups.value.find(g=>g.id===target.value);g.ids=[...new Set([...g.ids,...ids])]}message.value='成功导入2条；'+({new:'已创建计划和评审并关联',append:'已增量更新已有计划和评审',only:'仅导入，未创建或关联计划/评审'}[policy]);ask.value=false}function remove(c){cases.value=cases.value.filter(x=>x!==c);groups.value.forEach(g=>g.ids=g.ids.filter(x=>x!==c));message.value='已删除源用例并更新当前关联；正式功能保留历史证据'}function open(g,type){detailTitle.value=type==='plan'?g.plan:g.review;detailIds.value=g.ids;detail.value=true}function addProject(){if(!projectName.value.trim())return;assets.value.push({id:Date.now(),name:projectName.value.trim(),count:0,version:1,pinned:false});projectName.value=''}function sync(){assets.value.forEach(a=>{a.count++;a.version++})}window.addEventListener('msp-demo-import',()=>{tab.value='import';begin()});return{tab,groups,cases,ask,step,target,message,detail,detailTitle,detailIds,projectName,assets,ordered:computed(()=>[...assets.value].sort((a,b)=>Number(b.pinned)-Number(a.pinned))),begin,commit,remove,open,addProject,sync}}};
